import { useEffect, useRef, useState, type ReactNode } from 'react';
import { ArrowLeft, ArrowRight, ArrowUpRight, AtSign, Bot, Check, CheckCheck, ChevronDown, ChevronRight, CircleCheck, Clock3, Download, FileText, Flag, GitBranch, ListChecks, ListPlus, LockKeyhole, MessageSquare, MoreHorizontal, Paperclip, Pencil, Play, Plus, Send, ShieldCheck, Sparkles, Users, UserPlus, X } from 'lucide-react';
import { useDemo, type PageProps } from '@/store';
import { useWorks } from '@/work-store';
import { type Agent, type Run, type DemoState } from '@/model';
import {getAgentGovernance,governanceGate,portalReadinessLabels} from '@/governance';
import { type Work, type WorkMember, type WorkStatus, type MemberRole, type NewWorkInput, type ArtifactVersion, type Subtask, type SubtaskResult, latestTaskResult, getTaskResults, taskReadiness, taskContext, dependenciesReady, people, teams, authorName, canWrite, canSeeWorkItem, canSeeWorkRun, getWorkConversations, mainConversationId, conversationContext, workStatusLabels, roleLabels, subtaskLabels } from '@/work-model';
import { AgentIcon, EmptyState, Field, InfoTip, Notice, PageHeader, SearchBox, SectionTitle, StatusBadge } from '@/components/common';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import '@/styles/collaboration.css';

type DetailTab='chat'|'context'|'artifacts'|'runs';
type ModalAction='invite'|'assign'|'goal'|'scope'|'business'|'material'|'execute'|'human-result'|'remove'|'accept'|'edit-artifact'|'conversation'|null;
const statusOrder:WorkStatus[]=['active','waiting','review','completed'];
const artifactLabels={draft:'草稿',review:'待验收',accepted:'已验收',outdated:'需更新'};
const roleIcons={owner:Flag,collaborator:Users,observer:LockKeyhole};

function portalAvailability(state:DemoState,agent:Agent){
 const governance=getAgentGovernance(state,agent);
 const readiness=!agent.enabled||agent.deployment!=='available'||!agent.activeVersion?'not-ready':governance.readiness;
 return {readiness,label:portalReadinessLabels[readiness],reason:readiness==='not-ready'&&governance.readiness!=='not-ready'?'服务暂不可用，请联系负责人。':governance.userReason};
}
function PortalReadiness({state,agent}:{state:DemoState;agent:Agent}){const {readiness,label}=portalAvailability(state,agent);return <StatusBadge status={readiness==='ready'?'available':readiness==='limited'?'waiting':'blocked'}>{label}</StatusBadge>;}

function WorkBadge({status}:{status:WorkStatus}){return <span className={`cw-work-status ${status}`}><i/>{workStatusLabels[status]}</span>}
function PersonAvatar({name,agent=false,small=false}:{name:string;agent?:boolean;small?:boolean}){return <span className={`cw-avatar ${agent?'agent':''} ${small?'small':''}`}>{agent?<Bot size={small?13:17} strokeWidth={1.6}/>:name.slice(0,1)}</span>}
function ActorControl({members}:{members?:WorkMember[]}){const {actorId,setActorId}=useWorks();const candidates=members?people.filter(p=>members.some(m=>m.personId===p.id)):people;return <div className="cw-actor-control"><label htmlFor="work-current-actor">当前参与者</label><select id="work-current-actor" aria-label="当前参与者" value={actorId} onChange={e=>setActorId(e.target.value)}>{!candidates.some(p=>p.id===actorId)&&<option value={actorId}>{authorName(actorId)}</option>}{candidates.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><InfoTip label="参与者切换说明">在浏览器中切换示例成员，查看不同任务角色的操作与历史范围。</InfoTip></div>}
function UserCount({work}:{work:Work}){return <div className="cw-participants"><div className="cw-avatar-stack">{work.members.slice(0,3).map(m=><PersonAvatar key={m.personId} name={authorName(m.personId)} small/>)}</div><span>{work.members.length} 人 · {work.agents.length} Agent</span></div>}

export default function CollaborativePortal({page,selectedId,onNavigate}:PageProps){
 const works=useWorks();const demo=useDemo();const {state,actorId}=works;
 const [query,setQuery]=useState('');const [filter,setFilter]=useState('all');const [catalogType,setCatalogType]=useState<'all'|'agent'|'team'>('all');
 const [creating,setCreating]=useState(false);const [prefill,setPrefill]=useState<{type:'agent'|'team';id:string}>({type:'team',id:'TEAM-001'});const [detailTab,setDetailTab]=useState<DetailTab>('chat');
 const openWork=(id:string,tab:DetailTab='chat')=>{setDetailTab(tab);onNavigate('portal','work',id);};
 const create=(type:'agent'|'team'='team',id=type==='team'?'TEAM-001':'AGT-001')=>{setPrefill({type,id});setCreating(true);};
 useEffect(()=>{if(page==='catalog'&&selectedId&&demo.state.agents.some(a=>a.id===selectedId)){setPrefill({type:'agent',id:selectedId});setCreating(true);}},[page,selectedId]);
 const ownWorks=state.works.filter(w=>w.members.some(m=>m.personId===actorId));
 const work=state.works.find(w=>w.id===selectedId);
 const createDialog=<CreateWorkDialog key={`${prefill.type}-${prefill.id}-${creating}`} open={creating} onOpenChange={setCreating} prefill={prefill} onCreated={id=>{setCreating(false);openWork(id);}}/>;
 if(page==='work')return <>{work?<WorkRoom key={work.id} work={work} tab={detailTab} onTabChange={setDetailTab} onNavigate={onNavigate}/>:<><PageHeader title="任务不存在"/><EmptyState title="未找到该协作任务" action={<Button onClick={()=>onNavigate('portal','tasks')}>返回任务</Button>}/></>}{createDialog}</>;
 if(page==='catalog'){
  const agents=demo.state.agents.filter(a=>a.catalog==='listed'&&`${a.name}${a.description}${a.owner}`.toLowerCase().includes(query.toLowerCase()));
  const visibleTeams=teams.filter(t=>`${t.name}${t.description}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="cw-page"><PageHeader title="Agent 与团队" actions={<Button onClick={()=>create()}><Plus/>新建任务</Button>}/><div className="cw-toolbar"><div className="filter-pills">{[['all','全部'],['agent','专用 Agent'],['team','专家团队']].map(([value,label])=><button key={value} className={catalogType===value?'active':''} onClick={()=>setCatalogType(value as typeof catalogType)}>{label}</button>)}</div><SearchBox value={query} onChange={setQuery} placeholder="搜索 Agent 或团队…"/></div><div className="cw-catalog-grid">
   {catalogType!=='agent'&&visibleTeams.map(team=>{const members=team.agentIds.map(id=>demo.state.agents.find(a=>a.id===id)).filter((a):a is Agent=>!!a);const available=members.length===team.agentIds.length&&members.every(a=>portalAvailability(demo.state,a).readiness!=='not-ready');const limited=members.some(a=>portalAvailability(demo.state,a).readiness==='limited');const authorized=members.every(a=>a.access==='granted');return <article className="cw-executor-card team" key={team.id}><div className="cw-executor-top"><span className="cw-team-icon"><Users size={23} strokeWidth={1.6}/></span><StatusBadge status={!available?'blocked':limited?'waiting':'available'}>{!available?'暂不可用':limited?'仅支持查询':'可用'}</StatusBadge></div><h2>{team.name}</h2><p>{team.description}</p><div className="cw-team-members">{members.map(a=><span key={a.id}>{a.name}</span>)}</div><div className="cw-executor-footer"><span className="mono">{team.version}</span><Button size="sm" variant="outline" disabled={!available} onClick={()=>create('team',team.id)}>{!available?'暂不可用':authorized?'创建任务':'查看权限'}<ArrowRight/></Button></div></article>;})}
   {catalogType!=='team'&&agents.map(a=>{const availability=portalAvailability(demo.state,a);return <article className="cw-executor-card" key={a.id}><div className="cw-executor-top"><AgentIcon icon={a.icon}/><PortalReadiness state={demo.state} agent={a}/></div><h2>{a.name}</h2><p>{a.description}</p><div className="cw-agent-owner">{a.owner}<span className="mono">{a.activeVersion||'版本未知'}</span></div>{availability.readiness!=='ready'&&<p className="cw-empty-line">{availability.reason} 联系 {a.owner}。</p>}<div className="cw-executor-footer"><span>{a.category}</span><Button size="sm" variant="outline" disabled={availability.readiness==='not-ready'} onClick={()=>create('agent',a.id)}>{availability.readiness==='not-ready'?'暂不可用':a.access==='granted'?'创建任务':'申请访问'}<ArrowRight/></Button></div></article>;})}
   {!agents.length&&!visibleTeams.length&&<EmptyState/>}
  </div>{createDialog}</div>;
 }
 if(page==='inbox'){
  const decisions=ownWorks.flatMap(w=>w.decisions.filter(d=>d.status==='pending'&&d.approverId===actorId&&canSeeWorkItem(w,actorId,d)).map(d=>({w,d})));
  const assigned=ownWorks.flatMap(w=>w.subtasks.filter(t=>t.assigneeId===actorId&&(t.status!=='done'||taskReadiness(w,t)==='outdated')&&t.goalRevision===w.goalRevision&&canSeeWorkItem(w,actorId,t)).map(t=>({w,t})));
  const reviews=ownWorks.filter(w=>w.ownerId===actorId&&w.status==='review'&&w.artifacts.some(a=>a.goalRevision===w.goalRevision&&a.status==='review'&&canSeeWorkItem(w,actorId,a)));
  return <div className="cw-page"><PageHeader title="待我处理" actions={<ActorControl/>}/><div className="cw-inbox-sections"><InboxSection title="待决策" count={decisions.length}>{decisions.map(({w,d})=><button className="cw-inbox-row" key={d.id} onClick={()=>openWork(w.id)}><span className="cw-inbox-symbol"><ShieldCheck size={19}/></span><span><strong>{d.title}</strong><small>{w.title}</small></span><Badge variant="outline">{d.kind==='goal'?'目标变更':d.kind==='scope'?'范围变更':'业务确认'}</Badge><ChevronRight size={16}/></button>)}</InboxSection><InboxSection title="待验收" count={reviews.length}>{reviews.map(w=><button className="cw-inbox-row" key={w.id} onClick={()=>openWork(w.id,'artifacts')}><span className="cw-inbox-symbol"><FileText size={19}/></span><span><strong>{w.deliverableTitle}</strong><small>{w.title}</small></span><span className="cw-inbox-label">查看交付物</span><ChevronRight size={16}/></button>)}</InboxSection><InboxSection title="分派给我" count={assigned.length}>{assigned.map(({w,t})=><button className="cw-inbox-row" key={t.id} onClick={()=>openWork(w.id)}><span className="cw-inbox-symbol"><ListChecks size={19}/></span><span><strong>{t.title}</strong><small>{w.title}</small></span><Badge variant="outline">{taskReadiness(w,t)==='outdated'?'输入已更新':taskReadiness(w,t)==='waiting'?'等待依赖':subtaskLabels[t.status]}</Badge><ChevronRight size={16}/></button>)}</InboxSection></div>{createDialog}</div>;
 }
 const shown=ownWorks.filter(w=>(filter==='all'||w.status===filter)&&`${w.title}${w.goal}${w.deliverableTitle}`.toLowerCase().includes(query.toLowerCase()));
 return <div className="cw-page"><PageHeader title="任务" actions={<><ActorControl/><Button onClick={()=>create()}><Plus/>新建任务</Button></>}/><div className="cw-toolbar"><div className="filter-pills" role="group" aria-label="任务状态筛选"><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>全部<span>{ownWorks.length}</span></button>{statusOrder.map(s=><button className={filter===s?'active':''} key={s} onClick={()=>setFilter(s)}>{workStatusLabels[s]}</button>)}</div><SearchBox value={query} onChange={setQuery} placeholder="搜索任务或交付物…"/></div><div className="cw-work-grid">{shown.map(w=>{const done=w.subtasks.filter(t=>t.status==='done'&&t.goalRevision===w.goalRevision&&taskReadiness(w,t)==='ready').length;const count=w.subtasks.filter(t=>t.goalRevision===w.goalRevision).length;return <article className="cw-work-card" key={w.id}><div className="cw-work-card-top"><span className="cw-work-icon"><MessageSquare size={20} strokeWidth={1.5}/></span><WorkBadge status={w.status}/></div><button className="cw-work-name" onClick={()=>openWork(w.id)}><h2>{w.title}</h2><ArrowUpRight size={17}/></button><p className="cw-work-goal">{w.goal}</p><button className="cw-deliverable-link" onClick={()=>openWork(w.id,'artifacts')}><FileText size={15}/><span>{w.deliverableTitle}</span><ChevronRight size={13}/></button><div className="cw-task-progress"><div><span>子任务</span><strong>{done}<i> / {count}</i></strong></div><div className="cw-progress-track"><i style={{width:`${count?done/count*100:0}%`}}/></div></div><div className="cw-work-card-footer"><UserCount work={w}/><button aria-label={`进入${w.title}`} onClick={()=>openWork(w.id)}><ArrowRight size={17}/></button></div></article>;})}</div>{!shown.length&&<EmptyState title="暂无任务" action={<Button variant="outline" onClick={()=>create()}><Plus/>新建任务</Button>}/>} {createDialog}</div>;
}

function InboxSection({title,count,children}:{title:string;count:number;children:ReactNode}){return <section className="cw-inbox-section"><SectionTitle title={title} action={<span className="cw-count">{count}</span>}/>{count?children:<div className="cw-inbox-empty"><CheckCheck size={16}/>暂无待办</div>}</section>}

function CreateWorkDialog({open,onOpenChange,prefill,onCreated}:{open:boolean;onOpenChange:(value:boolean)=>void;prefill:{type:'agent'|'team';id:string};onCreated:(id:string)=>void}){
 const {state,requestAccess}=useDemo();const {actorId,createWork}=useWorks();
 const [form,setForm]=useState<NewWorkInput>({title:'',goal:'',deliverableTitle:'',executorType:prefill.type,executorId:prefill.id,invitees:[]});
 const [requestReason,setRequestReason]=useState('');
 const executors=form.executorType==='team'?teams.map(t=>({id:t.id,name:t.name})):state.agents.filter(a=>a.catalog==='listed').map(a=>({id:a.id,name:a.name}));
 const agentIds=form.executorType==='team'?teams.find(t=>t.id===form.executorId)?.agentIds||[]:[form.executorId];
 const selectedAgents=agentIds.map(id=>state.agents.find(a=>a.id===id));
 const invalid=selectedAgents.filter(a=>!a||portalAvailability(state,a).readiness==='not-ready'||a.access!=='granted');
 const limited=selectedAgents.filter((a):a is Agent=>!!a&&portalAvailability(state,a).readiness==='limited');
 const blocked=invalid.filter((a):a is Agent=>!!a&&a.enabled&&a.deployment==='available'&&a.access!=='granted');
 const submit=(e:React.FormEvent)=>{e.preventDefault();const id=createWork({...form,title:form.title.trim()||form.goal.trim().slice(0,24),deliverableTitle:form.deliverableTitle.trim()||'任务交付报告'});if(id)onCreated(id);};
 return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="cw-create-dialog" aria-describedby={undefined}><DialogHeader><DialogTitle>新建任务</DialogTitle></DialogHeader><form onSubmit={submit}><div className="dialog-body cw-form-body"><Field label="任务目标"><Textarea autoFocus placeholder="例如：分析 Q4 经营表现，形成面向管理层的经营汇报。" rows={3} required value={form.goal} onChange={e=>setForm({...form,goal:e.target.value})}/></Field><div className="cw-two-fields"><Field label="任务名称"><Input placeholder="根据目标命名" maxLength={48} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Field><Field label="主交付物"><Input placeholder="例如：Q4 经营汇报" required value={form.deliverableTitle} onChange={e=>setForm({...form,deliverableTitle:e.target.value})}/></Field></div><div className="cw-executor-choice"><div className="cw-field-heading"><span>执行者</span><InfoTip label="执行者说明">专用 Agent 与专家团队使用相同任务空间。实际执行时固定版本与目标修订。</InfoTip></div><div className="cw-segmented">{(['agent','team'] as const).map(type=><button type="button" aria-pressed={form.executorType===type} className={form.executorType===type?'active':''} key={type} onClick={()=>setForm({...form,executorType:type,executorId:type==='team'?'TEAM-001':'AGT-001'})}>{type==='agent'?<Bot size={15}/>:<Users size={15}/>} {type==='agent'?'专用 Agent':'专家团队'}</button>)}</div><select aria-label="选择执行者" value={form.executorId} onChange={e=>setForm({...form,executorId:e.target.value})}>{executors.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select>{form.executorType==='team'&&<div className="cw-selected-team">{agentIds.map(id=><span key={id}>{state.agents.find(a=>a.id===id)?.name||id}</span>)}</div>}</div>{invalid.length>0&&<div className="cw-access-warning"><LockKeyhole size={16}/><div><strong>需要可用且已授权的执行者</strong>{invalid.map((a,i)=><p key={a?.id||i}>{a?.name||'未找到 Agent'} · {a&&portalAvailability(state,a).readiness==='not-ready'?portalAvailability(state,a).reason:a?.access==='pending'?'访问申请待审':a?.access!=='granted'?'未授权':'服务不可用'}</p>)}{blocked.length>0&&<><Textarea aria-label="访问申请理由" placeholder="填写访问理由…" value={requestReason} onChange={e=>setRequestReason(e.target.value)}/><Button type="button" size="sm" variant="outline" disabled={!requestReason.trim()||blocked.every(a=>a.access==='pending')} onClick={()=>blocked.filter(a=>a.access!=='pending').forEach(a=>requestAccess(a.id,requestReason))}>提交访问申请</Button></>}</div></div>}{limited.length>0&&<Notice tone="warning">{limited.map(a=>a.name).join('、')}仅支持查询，暂不执行业务操作。</Notice>}<div><div className="cw-field-heading"><span>邀请协作者</span><InfoTip label="创建时邀请说明">受邀成员可查看此新任务的全部内容。创建者为负责人；之后可分别设置角色与历史范围。</InfoTip></div><div className="cw-invite-options">{people.filter(p=>p.id!==actorId).map(p=><label key={p.id}><input type="checkbox" checked={form.invitees?.includes(p.id)} onChange={()=>setForm({...form,invitees:form.invitees?.includes(p.id)?form.invitees.filter(id=>id!==p.id):[...(form.invitees||[]),p.id]})}/><PersonAvatar name={p.name} small/>{p.name}</label>)}</div></div></div><DialogFooter><Button type="button" variant="outline" onClick={()=>onOpenChange(false)}>取消</Button><Button type="submit" disabled={!form.goal.trim()||!form.deliverableTitle.trim()||invalid.length>0}>创建任务<ArrowRight/></Button></DialogFooter></form></DialogContent></Dialog>;
}

function WorkRoom({work,tab,onTabChange,onNavigate}:{work:Work;tab:DetailTab;onTabChange:(value:DetailTab)=>void;onNavigate:PageProps['onNavigate']}){
 const wapi=useWorks();const {actorId}=wapi;const demo=useDemo();
 const conversations=getWorkConversations(work);const mainId=mainConversationId(work);
 const [conversationId,setConversationId]=useState(()=>mainConversationId(work));
 const conversation=conversations.find(c=>c.id===conversationId)||conversations[0];
 const conversationAgents=work.agents.filter(a=>conversation.kind==='main'||conversation.agentIds.includes(a.agentId));
 const [conversationAgentIds,setConversationAgentIds]=useState<string[]>([]);
 const [contextOpen,setContextOpen]=useState(false);const [contextActor,setContextActor]=useState(actorId);
 const [highlightedMessageId,setHighlightedMessageId]=useState('');const [actionConversationId,setActionConversationId]=useState(mainId);
 const [message,setMessage]=useState('');const [mention,setMention]=useState('');const [sideOpen,setSideOpen]=useState(false);const [action,setAction]=useState<ModalAction>(null);
 const [title,setTitle]=useState('');const [detail,setDetail]=useState('');const [assignee,setAssignee]=useState(work.agents.find(a=>a.role==='expert')?.agentId||work.agents[0]?.agentId||work.ownerId);
 const [personId,setPersonId]=useState(people.find(p=>!work.members.some(m=>m.personId===p.id))?.id||'');const [memberRole,setMemberRole]=useState<MemberRole>('collaborator');const [history,setHistory]=useState<'all'|'from_join'>('all');const [scenario,setScenario]=useState<Run['scenario']>('normal');
 const [dependencyIds,setDependencyIds]=useState<string[]>([]);const [selectedTask,setSelectedTask]=useState<Subtask|null>(null);const [selectedArtifactId,setSelectedArtifactId]=useState<string>('');const [selectedPerson,setSelectedPerson]=useState('');
 const [rebindAgents,setRebindAgents]=useState(false);const [editingArtifactId,setEditingArtifactId]=useState('');const [actionActor,setActionActor]=useState(actorId);
 const [restricted,setRestricted]=useState(false);const [materialSource,setMaterialSource]=useState<'upload'|'knowledge'>('upload');
 const logRef=useRef<HTMLDivElement>(null);const fileRef=useRef<HTMLInputElement>(null);
 const member=work.members.find(m=>m.personId===actorId);const owner=work.ownerId===actorId;const writable=canWrite(work,actorId);const active=work.status!=='completed';
 const allVisibleMessages=work.messages.filter(m=>canSeeWorkItem(work,actorId,m));
 const visibleMessages=allVisibleMessages.filter(m=>(m.conversationId||mainId)===conversation.id);
 const visibleSubtasks=work.subtasks.filter(t=>canSeeWorkItem(work,actorId,t));
 const artifacts=work.artifacts.filter(a=>canSeeWorkItem(work,actorId,a)).sort((a,b)=>b.number-a.number);
 const selectedArtifact=artifacts.find(a=>a.id===selectedArtifactId)||artifacts[0];const pendingDecisions=work.decisions.filter(d=>d.status==='pending'&&canSeeWorkItem(work,actorId,d));
 const materials=work.materials.filter(m=>canSeeWorkItem(work,actorId,m));
 const affectedAgents=work.agents.filter(a=>visibleSubtasks.some(t=>t.assigneeId===a.agentId&&t.goalRevision===work.goalRevision&&t.status!=='done')&&!governanceGate(demo.state,a.agentId,'general',a.releaseId).allowed);
 const limitedAgents=work.status==='completed'?[]:work.agents.filter(a=>{const current=demo.state.agents.find(x=>x.id===a.agentId);return current&&getAgentGovernance(demo.state,current,a.releaseId).readiness==='limited';});
 const coordinator=work.agents.find(a=>a.role==='coordinator')||work.agents[0];
 const businessGate=coordinator?governanceGate(demo.state,coordinator.agentId,'protected-action',coordinator.releaseId):{allowed:false,reason:'执行者暂不可用。'};
 const runIds=new Set(visibleSubtasks.flatMap(t=>[...(t.runIds||[]),t.runId]).filter(Boolean));work.decisions.filter(d=>canSeeWorkItem(work,actorId,d)).forEach(d=>d.runId&&runIds.add(d.runId));
 const runs=demo.state.runs.filter(r=>runIds.has(r.id)&&canSeeWorkRun(wapi.state.works,actorId,r));
 const visibleRunIds=new Set(runs.map(r=>r.id));
 const editingArtifact=artifacts.find(a=>a.id===editingArtifactId);
 const context=conversationContext(work,actorId,conversation.id);
 const actionConversation=conversations.find(c=>c.id===actionConversationId)||conversations[0];
 const assignmentAgents=work.agents.filter(a=>actionConversation.kind==='main'||actionConversation.agentIds.includes(a.agentId));
 const showAction=(type:ModalAction)=>{setActionActor(actorId);setActionConversationId(conversation.id);if(type==='assign'){setAssignee(conversationAgents.find(a=>a.role==='expert')?.agentId||conversationAgents[0]?.agentId||actorId);setDependencyIds([]);}setAction(type);};
 const openAction=(type:ModalAction)=>{setTitle('');setDetail('');setRestricted(false);setRebindAgents(false);if(type==='conversation')setConversationAgentIds([]);showAction(type);};
 useEffect(()=>{if(!highlightedMessageId)logRef.current?.scrollTo({top:logRef.current.scrollHeight,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});},[visibleMessages.length,tab,conversation.id]);
 useEffect(()=>{if(!highlightedMessageId||tab!=='chat')return;const element=Array.from(logRef.current?.querySelectorAll<HTMLElement>('[data-work-message]')||[]).find(el=>el.dataset.workMessage===highlightedMessageId);element?.scrollIntoView({block:'center',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});element?.focus({preventScroll:true});const timer=window.setTimeout(()=>setHighlightedMessageId(''),3000);return()=>window.clearTimeout(timer);},[highlightedMessageId,conversation.id,tab]);
 const switchConversation=(id:string,sourceMessageId?:string)=>{if(!conversations.some(c=>c.id===id))return;if(sourceMessageId&&!allVisibleMessages.some(m=>m.id===sourceMessageId&&(m.conversationId||mainId)===id)){demo.notify('当前身份无法查看来源消息。');return;}setConversationId(id);setHighlightedMessageId(sourceMessageId||'');setMessage('');setMention('');setAction(null);setSideOpen(false);onTabChange('chat');};
 const send=()=>{if(!writable||!message.trim())return;wapi.sendMessage(work.id,message.trim(),mention||undefined,conversation.id);setMessage('');};
 useEffect(()=>{setAction(null);setTitle('');setDetail('');setSelectedArtifactId('');setEditingArtifactId('');setSelectedTask(null);setSelectedPerson('');setSideOpen(false);setMessage('');setMention('');setConversationId(mainId);setHighlightedMessageId('');setContextOpen(false);setConversationAgentIds([]);},[actorId,work.id]);
 const isBusinessRetry=(task:Subtask)=>task.status==='blocked'&&work.decisions.some(d=>d.kind==='business'&&!!d.runId&&(d.runId===task.runId||task.runIds?.includes(d.runId)));
 const memberName=(id:string)=>work.agents.find(a=>a.agentId===id)?.name||authorName(id);
 const download=(a:ArtifactVersion)=>{const visible=work.artifacts.find(item=>item.id===a.id&&canSeeWorkItem(work,actorId,item));if(!visible){demo.notify('当前身份无权读取此成果版本。');return;}const data=`# ${a.title}\n\n版本 v${a.number} · 目标 r${a.goalRevision}\n\n${a.content}`;const url=URL.createObjectURL(new Blob([data],{type:'text/markdown;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`${a.title}-v${a.number}.md`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 if(!member)return <><PageHeader title="无权查看此任务" actions={<ActorControl/>}/><EmptyState title="你不是此任务成员" action={<Button variant="outline" onClick={()=>onNavigate('portal','tasks')}>返回任务</Button>}/></>;
 const latestCurrent=artifacts.find(a=>a.goalRevision===work.goalRevision);
 const canAccept=owner&&selectedArtifact?.number===Math.max(0,...work.artifacts.filter(a=>a.goalRevision===work.goalRevision).map(a=>a.number))&&selectedArtifact?.goalRevision===work.goalRevision&&selectedArtifact.status==='review'&&!work.decisions.some(d=>d.status==='pending')&&work.subtasks.some(t=>t.goalRevision===work.goalRevision)&&work.subtasks.filter(t=>t.goalRevision===work.goalRevision).every(t=>t.status==='done'&&taskReadiness(work,t)==='ready');
 const sidebar=<><section className="cw-side-section"><SectionTitle title="成员" action={<InfoTip label="任务权限说明">负责人确认目标变更并验收交付物；协作者可讨论和分派子任务；观察者仅查看。资源调用仍需单独授权。</InfoTip>}/><div className="cw-members">{work.members.map(m=>{const RoleIcon=roleIcons[m.role];return <div className="cw-member" key={m.personId}><PersonAvatar name={authorName(m.personId)}/><div><strong>{authorName(m.personId)}</strong><small>{roleLabels[m.role]}</small></div>{m.personId===actorId&&<span className="cw-you">我</span>}<RoleIcon size={13} className="cw-member-role-icon"/>{owner&&m.role!=='owner'&&<button aria-label={`移除${authorName(m.personId)}`} className="cw-member-remove" onClick={()=>{setSelectedPerson(m.personId);showAction('remove');}}><X size={13}/></button>}</div>;})}</div><div className="cw-agent-roster">{work.agents.map(a=><div className="cw-member cw-agent-member" key={a.agentId}><PersonAvatar name={a.name} agent/><div><strong>{a.name}</strong><small>{a.role==='coordinator'?'协调 Agent':'专家'} · {a.version}</small></div><InfoTip label={`${a.name}版本信息`}>{a.assignment}<br/>{a.agentId} · {a.releaseId}</InfoTip></div>)}</div></section>
  <section className="cw-side-section"><SectionTitle title="子任务" action={<Button variant="ghost" size="icon-xs" aria-label="派发子任务" disabled={!writable||!active} onClick={()=>openAction('assign')}><Plus/></Button>}/><SubtaskFlow work={work} onNavigate={onNavigate}/></section>
  <section className="cw-side-section"><SectionTitle title="共享资料" action={<Button variant="ghost" size="icon-xs" aria-label="添加共享资料" disabled={!writable||!active} onClick={()=>openAction('material')}><Plus/></Button>}/>{materials.map(m=><div className="cw-material" key={m.id}><FileText size={17}/><div><strong>{m.name}</strong><span>{m.source==='knowledge'?'知识引用':'任务资料'} · {authorName(m.ownerId)}</span>{m.detail&&<p>{m.detail}</p>}</div></div>)}{!materials.length&&<p className="cw-empty-line">暂无可见资料</p>}</section></>;
 return <div className="cw-page cw-room-page"><button className="cw-back" onClick={()=>onNavigate('portal','tasks')}><ArrowLeft size={14}/>任务</button><PageHeader title={work.title} actions={<><ActorControl members={work.members}/><Button variant="outline" className="cw-details-button" onClick={()=>setSideOpen(true)}><Users/>任务详情</Button><Button variant="outline" disabled={!owner} onClick={()=>openAction('invite')}><UserPlus/>邀请成员</Button></>}/><div className="cw-room-objective"><div><span className="cw-goal-revision">目标 r{work.goalRevision}</span><p>{work.goal}</p></div><WorkBadge status={work.status}/></div><div className="cw-room-deliverable"><FileText size={17}/><button onClick={()=>onTabChange('artifacts')}>{work.deliverableTitle}<ChevronRight size={14}/></button>{latestCurrent?<span>v{latestCurrent.number} · {artifactLabels[latestCurrent.status]}</span>:<span>无可见版本</span>}</div>
  {affectedAgents.length>0&&<Notice tone="warning">{affectedAgents.map(a=>a.name).join('、')}暂不可用，相关执行已暂停。历史内容仍可查看，请联系 Agent 负责人。</Notice>}{!affectedAgents.length&&limitedAgents.length>0&&<Notice tone="warning">{limitedAgents.map(a=>a.name).join('、')}仅支持查询，业务操作暂不可用。</Notice>}<div className="cw-work-layout"><div className="cw-work-main"><Tabs value={tab} onValueChange={v=>onTabChange(v as DetailTab)}><TabsList variant="line" className="cw-room-tabs"><TabsTrigger value="chat"><MessageSquare/>协作</TabsTrigger><TabsTrigger value="context"><ListChecks/>共享上下文</TabsTrigger><TabsTrigger value="artifacts"><FileText/>交付物{artifacts.length>0&&<span className="cw-tab-count">{artifacts.length}</span>}</TabsTrigger><TabsTrigger value="runs"><ActivityIcon/>执行记录</TabsTrigger></TabsList></Tabs>
   {tab==='chat'&&<div className="cw-chat-workspace">
    <nav className="cw-conversations" aria-label="任务会话"><div className="cw-conversations-title"><strong>会话</strong><Button variant="ghost" size="icon-xs" aria-label="新建会话" disabled={!writable} onClick={()=>openAction('conversation')}><Plus/></Button></div><div className="cw-conversation-list">{conversations.map(c=><button className={`cw-conversation-item ${c.id===conversation.id?'active':''}`} key={c.id} aria-current={c.id===conversation.id?'page':undefined} onClick={()=>switchConversation(c.id)}>{c.kind==='main'?<MessageSquare size={14}/>:<GitBranch size={14}/>}<span>{c.title}</span></button>)}</div></nav>
    <div className="cw-conversation-content"><header className="cw-conversation-header"><div className="cw-conversation-heading"><strong>{conversation.title}</strong><select className="cw-conversation-select" aria-label="当前会话" value={conversation.id} onChange={e=>switchConversation(e.target.value)}>{conversations.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select><InfoTip label="会话上下文说明">各会话共用任务目标、资料、已确认决策和已提交的子任务成果。执行按依赖读取成果版本；聊天用于讨论。</InfoTip><div className="cw-conversation-header-actions"><Button variant="ghost" size="icon-xs" aria-label="查看上下文" onClick={()=>{setContextActor(actorId);setContextOpen(true);}}><ListChecks/></Button><Button variant="ghost" size="icon-xs" className="cw-conversation-new" aria-label="新建会话" disabled={!writable} onClick={()=>openAction('conversation')}><Plus/></Button></div></div><div className="cw-conversation-agents" aria-label="会话参与 Agent">{conversationAgents.map(a=><span key={a.agentId}><Bot size={11}/>{a.name}</span>)}</div></header>
    <div className="cw-chat-log" ref={logRef} aria-label={`${conversation.title}消息`}>
     {visibleMessages.map(m=>{const source=m.sourceMessageId&&m.sourceConversationId?allVisibleMessages.find(item=>item.id===m.sourceMessageId&&(item.conversationId||mainId)===m.sourceConversationId):undefined;const sourceConversation=source&&conversations.find(c=>c.id===(source.conversationId||mainId));return <div className={`cw-message-entry ${highlightedMessageId===m.id?'cw-message-highlight':''}`} key={m.id} data-work-message={m.id} tabIndex={-1}>
      {m.kind==='system'?<div className="cw-system-message"><GitBranch size={12}/><span>{m.text}</span></div>:<article className={`cw-message ${m.kind==='agent'?'agent':''} ${m.authorId===actorId?'mine':''}`}><PersonAvatar name={m.authorName} agent={work.agents.some(a=>a.agentId===m.authorId)}/><div><div className="cw-message-meta"><strong>{m.authorName}</strong>{m.kind==='question'&&m.mentionId&&<span>@{memberName(m.mentionId)}</span>}{m.kind==='assignment'&&<span>派发子任务</span>}{m.kind==='decision'&&<span>决策</span>}{m.sourceMessageId&&m.goalRevision!==undefined&&<span className={`cw-source-revision ${m.goalRevision!==work.goalRevision?'old':''}`}>来源 r{m.goalRevision}</span>}<time>{m.time}</time></div><div className="cw-message-body">{m.text}</div></div></article>}
      {sourceConversation&&source&&<div className="cw-message-actions"><button className="cw-message-source" onClick={()=>switchConversation(sourceConversation.id,source.id)} aria-label={`返回来源会话：${sourceConversation.title}`}><GitBranch size={11}/>{sourceConversation.title}<ArrowUpRight size={11}/></button></div>}
     </div>;})}
     {!visibleMessages.length&&<EmptyState title={conversation.kind==='topic'?'开始专题讨论':member.history==='from_join'?'暂无加入后的消息':'开始协作'}/>}
    </div>
    {pendingDecisions.length>0&&<div className="cw-decision-stack">{pendingDecisions.map(d=><div className="cw-decision-card" key={d.id}><div className="cw-decision-icon"><ShieldCheck size={18}/></div><div className="cw-decision-content"><div><strong>{d.title}</strong><Badge variant="outline">{d.kind==='goal'?'目标变更':d.kind==='scope'?'范围变更':'业务执行'}</Badge></div><p>{d.detail}</p>{d.newGoal&&<blockquote>{d.newGoal}</blockquote>}<small>{authorName(d.proposedBy)}提出 · 待{authorName(d.approverId)}确认</small>{d.kind==='business'&&<p className="cw-consequence">批准后执行上述动作，并保留执行记录；拒绝不执行。</p>}{d.approverId===actorId&&<div className="cw-decision-actions"><Button size="sm" disabled={d.kind==='business'&&!businessGate.allowed} title={d.kind==='business'&&!businessGate.allowed?businessGate.reason:undefined} onClick={()=>wapi.resolveDecision(work.id,d.id,true)}>批准{d.kind==='business'?'执行':'变更'}</Button><Button size="sm" variant="outline" onClick={()=>wapi.resolveDecision(work.id,d.id,false)}>驳回</Button></div>}</div></div>)}</div>}
    <div className="cw-chat-composer"><div className="cw-composer-tools"><Button size="xs" variant="ghost" disabled={!writable||!active} onClick={()=>openAction('assign')}><ListPlus/>派发子任务</Button><Button size="xs" variant="ghost" disabled={!writable} onClick={()=>{setDetail('');setTitle(work.goal);setRebindAgents(false);showAction('goal');}}><Flag/>变更目标</Button><Button size="xs" variant="ghost" disabled={!writable||!active||!businessGate.allowed} title={!businessGate.allowed?businessGate.reason:undefined} onClick={()=>openAction('business')}><ShieldCheck/>请求执行</Button><Button size="xs" variant="ghost" disabled={!writable||!active} onClick={()=>openAction('material')}><Paperclip/>资料</Button></div><Textarea aria-label={`${conversation.title}消息内容`} rows={3} placeholder={!writable?'观察者仅可查看':'输入消息，或 @ 成员提问…'} value={message} disabled={!writable} onChange={e=>setMessage(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();send();}}}/><div className="cw-composer-bottom"><div className="cw-message-target"><AtSign size={13}/><select aria-label="消息对象" value={mention} onChange={e=>setMention(e.target.value)} disabled={!writable}><option value="">本会话</option>{conversationAgents.map(a=><option key={a.agentId} value={a.agentId}>{a.name}</option>)}{work.members.filter(m=>m.personId!==actorId).map(m=><option key={m.personId} value={m.personId}>{authorName(m.personId)}</option>)}</select><InfoTip label="消息与派活的区别">普通消息用于讨论；@用于定向提问。通过子任务提交成果、设置依赖，后续执行会读取相应版本。</InfoTip></div><Button size="sm" disabled={!writable||!message.trim()} onClick={send}>发送<Send/></Button></div></div>
    </div></div>}
   {tab==='context'&&<SharedWorkContext work={work} onNavigate={onNavigate} onAddMaterial={()=>openAction('material')}/>}
   {tab==='artifacts'&&<div className="cw-artifacts-view"><div className="cw-artifact-toolbar"><select aria-label="交付物版本" value={selectedArtifact?.id||''} onChange={e=>setSelectedArtifactId(e.target.value)}>{artifacts.map(a=><option key={a.id} value={a.id}>v{a.number} · 目标 r{a.goalRevision} · {artifactLabels[a.status]}</option>)}</select><Button variant="outline" size="sm" disabled={!writable||!active} onClick={()=>{setSelectedArtifactId('');wapi.assembleArtifact(work.id);}}><Sparkles/>汇总成果</Button></div>{selectedArtifact?<><div className="cw-document"><div className="cw-document-heading"><span className="cw-document-version">VERSION {selectedArtifact.number.toString().padStart(2,'0')}</span><h2>{selectedArtifact.title}</h2><div><span>目标 r{selectedArtifact.goalRevision}</span><span>{selectedArtifact.createdAt}</span><span>{artifactLabels[selectedArtifact.status]}</span></div></div>{(selectedArtifact.status==='outdated'||selectedArtifact.goalRevision!==work.goalRevision)&&<Notice tone="warning">此版本对应旧目标，请更新后重新验收。</Notice>}<DocumentBody content={selectedArtifact.content}/>{selectedArtifact.acceptedBy&&<div className="cw-accept-stamp"><CircleCheck size={18}/><span>{authorName(selectedArtifact.acceptedBy)}已验收 · {selectedArtifact.acceptedAt}</span></div>}</div><div className="cw-artifact-actions"><Button variant="outline" size="sm" onClick={()=>download(selectedArtifact)}><Download/>下载</Button><Button variant="outline" size="sm" disabled={!writable||!active} onClick={()=>{setDetail(selectedArtifact.content);setTitle(selectedArtifact.title);setEditingArtifactId(selectedArtifact.id);showAction('edit-artifact');}}><Pencil/>修改成果</Button><Button size="sm" disabled={!canAccept} onClick={()=>showAction('accept')}><CheckCheck/>验收交付物</Button><InfoTip label="验收条件">负责人验收当前目标对应的成果版本。当前子任务需全部完成，且没有待决策事项。验收后任务完成，历史版本保留。</InfoTip></div></>:<EmptyState title="尚无可见交付物"/>}</div>}
   {tab==='runs'&&<div className="cw-run-list">{runs.map(r=><button className="cw-run-row" key={r.id} onClick={()=>onNavigate('portal','run',r.id)}><span className="cw-run-icon"><Play size={16}/></span><div><strong>{demo.state.agents.find(a=>a.id===r.agentId)?.name||r.agentId}</strong><p>{r.input}</p><small>{r.id} · {r.version}</small><span className="cw-run-conversation"><MessageSquare size={10}/>{conversations.find(c=>c.id===(r.conversationId||mainId))?.title||'总协作'}</span></div><StatusBadge status={r.status}/><ArrowUpRight size={15}/></button>)}{!runs.length&&<EmptyState title="暂无可见执行记录"/>}</div>}
  </div><aside className="cw-sidebar">{sidebar}</aside></div>
  <Dialog open={sideOpen} onOpenChange={setSideOpen}><DialogContent className="cw-detail-dialog" aria-describedby={undefined}><DialogHeader><DialogTitle>任务详情</DialogTitle></DialogHeader><div className="cw-mobile-sidebar">{sidebar}</div></DialogContent></Dialog>
  <Dialog open={contextOpen&&contextActor===actorId} onOpenChange={setContextOpen}><DialogContent className="cw-context-dialog" aria-describedby={undefined}><DialogHeader><DialogTitle>{conversation.title} · 上下文</DialogTitle></DialogHeader><pre className="cw-context-preview" tabIndex={0} aria-label="当前会话上下文">{context?.input||'暂无可见上下文'}</pre><DialogFooter><Button variant="outline" onClick={()=>setContextOpen(false)}>关闭</Button></DialogFooter></DialogContent></Dialog>
  <Dialog open={action!==null&&actionActor===actorId&&(action!=='edit-artifact'||!!editingArtifact)} onOpenChange={open=>!open&&setAction(null)}><DialogContent className={`cw-action-dialog ${action==='edit-artifact'?'cw-edit-dialog':''}`} aria-describedby={undefined}><DialogHeader><DialogTitle>{{invite:'邀请成员',assign:'派发子任务',goal:'变更目标',scope:'扩大执行范围',business:'请求执行业务动作',material:'添加共享资料',execute:selectedTask&&isBusinessRetry(selectedTask)?'重试业务动作':selectedTask?.status==='blocked'?'重试子任务':'执行子任务','human-result':'提交子任务结果',remove:'移除成员',accept:'验收交付物','edit-artifact':'修改成果',conversation:'新建会话'}[action||'invite']}</DialogTitle></DialogHeader><div className="dialog-body cw-form-body">
   {action==='conversation'&&<><Field label="会话名称"><Input autoFocus maxLength={48} placeholder="例如：经营数据核对" value={title} onChange={e=>setTitle(e.target.value)}/></Field><Field label="参与 Agent"><div className="cw-conversation-agent-picker" role="group">{work.agents.map(a=><label key={a.agentId}><input type="checkbox" checked={conversationAgentIds.includes(a.agentId)} onChange={e=>setConversationAgentIds(ids=>e.target.checked?[...ids,a.agentId]:ids.filter(id=>id!==a.agentId))}/><Bot size={14}/><span>{a.name}</span></label>)}</div></Field><div className="cw-conversation-permissions"><Users size={13}/><span>任务成员共同参与</span><InfoTip label="会话成员与权限">真人成员、角色和历史共享范围继承当前任务。至少选择一位任务内已绑定的 Agent；创建会话不会启动执行。</InfoTip></div></>}
   {action==='invite'&&<><Field label="成员"><select value={personId} onChange={e=>setPersonId(e.target.value)}><option value="">选择成员</option>{people.filter(p=>!work.members.some(m=>m.personId===p.id)).map(p=><option value={p.id} key={p.id}>{p.name} · {p.department}</option>)}</select></Field><Field label="角色"><select value={memberRole} onChange={e=>setMemberRole(e.target.value as MemberRole)}><option value="collaborator">协作者</option><option value="observer">观察者</option></select></Field><Field label="历史共享范围" hint="当前目标和分工为共同基线。加入后范围不展示此前的消息、资料、成果和执行内容。"><select value={history} onChange={e=>setHistory(e.target.value as typeof history)}><option value="all">全部历史</option><option value="from_join">仅加入后内容</option></select></Field><Notice tone="warning">受邀者可查看所选范围内的任务内容。请确认资料允许向该成员共享。</Notice></>}
   {action==='assign'&&<><div className="cw-assignment-origin"><MessageSquare size={13}/>{actionConversation.title}</div><Field label="子任务"><Input autoFocus placeholder="明确要完成的工作与产出" value={title} onChange={e=>setTitle(e.target.value)}/></Field><Field label="执行者"><select value={assignee} onChange={e=>setAssignee(e.target.value)}>{assignmentAgents.map(a=><option key={a.agentId} value={a.agentId}>{a.name}</option>)}{work.members.filter(m=>m.role!=='observer').map(m=><option key={m.personId} value={m.personId}>{authorName(m.personId)}</option>)}</select></Field><DependencyPicker work={work} value={dependencyIds} onChange={setDependencyIds}/></>}
   {(action==='goal'||action==='scope')&&<><Field label="变更类型"><select value={action} onChange={e=>{const type=e.target.value as 'goal'|'scope';showAction(type);setTitle(type==='goal'?work.goal:'');setDetail('');setRebindAgents(false);}}><option value="goal">任务目标</option><option value="scope">执行范围</option></select></Field><Field label={action==='goal'?'新目标':'范围调整内容'}><Textarea autoFocus rows={4} value={title} onChange={e=>setTitle(e.target.value)}/></Field><Field label="变更原因"><Textarea rows={2} value={detail} onChange={e=>setDetail(e.target.value)} placeholder="说明需要调整的内容…"/></Field>{action==='scope'&&<div className="cw-scope-rebind"><label><input type="checkbox" checked={rebindAgents} onChange={e=>setRebindAgents(e.target.checked)}/>重新绑定执行者当前版本</label><InfoTip label="执行者版本重新绑定说明">仅已授权、服务可用且已交付的当前版本可重新绑定。负责人批准后记录新版本快照，旧执行记录保留。</InfoTip></div>}<Notice tone="warning">负责人批准后更新目标修订，已有成果和相关子任务需重新检查；已执行的外部动作不会撤销。</Notice></>}
   {action==='business'&&<><Field label="拟执行的业务动作"><Textarea autoFocus rows={4} placeholder="例如：向指定收件人发送已验收的经营汇报，说明内容与影响范围。" value={detail} onChange={e=>setDetail(e.target.value)}/></Field><Notice tone="warning">此申请会交给负责人确认。批准后才启动该动作的执行；普通群聊消息不会授予执行权限。</Notice></>}
   {action==='material'&&<><Field label="资料名称"><Input autoFocus placeholder="例如：Q4 经营数据摘要" value={title} onChange={e=>setTitle(e.target.value)}/></Field><Field label="内容摘要"><Textarea rows={4} value={detail} onChange={e=>setDetail(e.target.value)}/></Field><div className="cw-file-row"><input type="file" accept=".txt,.md,.csv" ref={fileRef} className="sr-only" aria-label="选择文本资料" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>256000){demo.notify('请选择小于 250 KB 的文本资料。');return;}setTitle(file.name);setDetail((await file.text()).slice(0,12000));}}/><Button variant="outline" size="sm" onClick={()=>fileRef.current?.click()}><Paperclip/>选择文本文件</Button><span>仅在当前浏览器读取</span></div><label className="cw-restricted-check"><input type="checkbox" checked={restricted} onChange={e=>setRestricted(e.target.checked)}/>该资料含仅本人可见或未授权内容</label>{restricted?<Notice tone="warning">受限资料不能加入任务共享内容。请先提供获准共享的摘要。</Notice>:<Notice>加入后对符合历史范围的任务成员及执行 Agent 可见。</Notice>}</>}
   {action==='execute'&&selectedTask&&<>{isBusinessRetry(selectedTask)&&<Notice tone="warning">将再次执行已确认的业务动作，请先确认上次执行未产生重复提交。此次重试需要负责人确认。</Notice>}<div className="cw-action-context"><strong>{selectedTask.title}</strong><span>{memberName(selectedTask.assigneeId)} · 目标 r{work.goalRevision}</span></div><Field label="运行情境"><select value={scenario} onChange={e=>setScenario(e.target.value as Run['scenario'])}><option value="normal">正常完成</option><option value="failure">工具异常</option><option value="guardrail">策略拦截</option><option value="timeout">运行超时</option></select></Field></>}
   {action==='human-result'&&selectedTask&&<><div className="cw-action-context"><strong>{selectedTask.title}</strong></div><Field label="任务结果"><Textarea autoFocus rows={5} value={detail} onChange={e=>setDetail(e.target.value)}/></Field></>}
   {action==='remove'&&<Notice tone="warning">移除 {authorName(selectedPerson)} 后，该成员无法继续查看此任务或发起操作；已有记录保留，已经看过或保存的内容不会被收回。</Notice>}
   {action==='accept'&&selectedArtifact&&<><div className="cw-action-context"><strong>{selectedArtifact.title}</strong><span>v{selectedArtifact.number} · 目标 r{selectedArtifact.goalRevision}</span></div><Notice tone="warning">验收后将此版本固定为任务交付物，并将任务标记为已完成。继续迭代需要通过目标变更开启新的修订。</Notice></>}
   {action==='edit-artifact'&&editingArtifact&&<><Field label="交付物标题"><Input value={title} onChange={e=>setTitle(e.target.value)}/></Field><Field label="交付物正文"><Textarea autoFocus rows={16} value={detail} onChange={e=>setDetail(e.target.value)}/></Field></>}
  </div><DialogFooter><Button variant="outline" onClick={()=>setAction(null)}>取消</Button><Button variant={action==='remove'?'destructive':'default'} disabled={(action==='conversation'&&(!title.trim()||!conversationAgentIds.length))||(action==='invite'&&!personId)||(action==='assign'&&!title.trim())||(action==='goal'&&(!title.trim()||!detail.trim()))||(action==='scope'&&!title.trim()&&!detail.trim()&&!rebindAgents)||(action==='business'&&(!detail.trim()||!businessGate.allowed))||(action==='material'&&(!title.trim()||!detail.trim()||restricted))||(action==='execute'&&!!selectedTask&&(!governanceGate(demo.state,selectedTask.assigneeId,isBusinessRetry(selectedTask)?'protected-action':'general',work.agents.find(a=>a.agentId===selectedTask.assigneeId)?.releaseId).allowed||isBusinessRetry(selectedTask)&&!owner))||(action==='human-result'&&!detail.trim())||(action==='edit-artifact'&&(!detail.trim()||!title.trim()))} onClick={()=>{
   if(action==='conversation'){const id=wapi.createConversation(work.id,title.trim(),conversationAgentIds);if(!id)return;setConversationId(id);setMessage('');setMention('');setHighlightedMessageId('');onTabChange('chat');}
   if(action==='invite')wapi.inviteMember(work.id,personId,memberRole,history);
   if(action==='assign')wapi.assignSubtask(work.id,title.trim(),assignee,actionConversation.id,dependencyIds);
   if(action==='goal')wapi.proposeDecision(work.id,'goal',detail.trim(),title.trim());
   if(action==='scope')wapi.proposeDecision(work.id,'scope',[title.trim()&&`范围：${title.trim()}`,detail.trim()&&`原因：${detail.trim()}`,rebindAgents&&'重新绑定执行者当前已交付版本。'].filter(Boolean).join('\n'),undefined,rebindAgents);
   if(action==='business')wapi.requestBusiness(work.id,detail.trim());
   if(action==='material')wapi.addMaterial(work.id,{name:title.trim(),detail:detail.trim(),source:materialSource,restricted});
   if(action==='execute'&&selectedTask)wapi.startSubtask(work.id,selectedTask.id,scenario);
   if(action==='human-result'&&selectedTask)wapi.completeHumanSubtask(work.id,selectedTask.id,detail.trim());
   if(action==='remove')wapi.removeMember(work.id,selectedPerson);
   if(action==='accept'&&selectedArtifact)wapi.acceptArtifact(work.id,selectedArtifact.id);
   if(action==='edit-artifact'&&editingArtifact&&canSeeWorkItem(work,actorId,editingArtifact)){setSelectedArtifactId('');wapi.saveArtifactVersion(work.id,detail.trim(),title.trim());}
   setAction(null);
  }}>{action==='conversation'?'创建会话':action==='invite'?'邀请成员':action==='assign'?'派发子任务':action==='execute'?(selectedTask&&isBusinessRetry(selectedTask)?'确认重试业务动作':selectedTask?.status==='blocked'?'重试执行':'开始执行'):action==='remove'?'确认移除':action==='accept'?'确认验收':action==='material'?'共享资料':action==='edit-artifact'?'提交新版本':action==='human-result'?'提交结果':'提交申请'}</Button></DialogFooter></DialogContent></Dialog>
 </div>;
}

function DocumentBody({content}:{content:string}){return <div className="cw-document-body">{content.split('\n').map((line,i)=>/^#{1,3}\s/.test(line)?<h3 key={i}>{line.replace(/^#{1,3}\s/,'')}</h3>:line.trim()?<p key={i}>{line}</p>:<div className="cw-document-space" key={i}/>)}</div>}
function ActivityIcon(){return <GitBranch size={14}/>}




function DependencyPicker({work,value,onChange,excludeId}:{work:Work;value:string[];onChange:(ids:string[])=>void;excludeId?:string}){
 const {actorId}=useWorks();
 const options=work.subtasks.filter(t=>t.id!==excludeId&&t.goalRevision===work.goalRevision&&canSeeWorkItem(work,actorId,t));
 return <Field label="依赖成果"><div className="cw-dependency-picker" role="group" aria-label="依赖成果">{options.map(t=>{const result=latestTaskResult(t);const visible=result&&canSeeWorkItem(work,actorId,result);return <label key={t.id}><input type="checkbox" checked={value.includes(t.id)} onChange={e=>onChange(e.target.checked?[...value,t.id]:value.filter(id=>id!==t.id))}/><span>{t.title}</span><small>{visible?`v${result.version}`:'待提交'}</small></label>;})}{!options.length&&<p className="cw-empty-line">暂无其他子任务</p>}</div></Field>;
}

function SubtaskFlow({work,onNavigate,expanded=false}:{work:Work;onNavigate:PageProps['onNavigate'];expanded?:boolean}){
 const wapi=useWorks();const {actorId}=wapi;const demo=useDemo();
 const [taskId,setTaskId]=useState('');const [mode,setMode]=useState<'execute'|'dependencies'|'result'|null>(null);const [modalActor,setModalActor]=useState(actorId);
 const [resultId,setResultId]=useState('');const [resultTaskId,setResultTaskId]=useState('');const [viewActor,setViewActor]=useState(actorId);
 const [content,setContent]=useState('');const [dependencies,setDependencies]=useState<string[]>([]);const [scenario,setScenario]=useState<Run['scenario']>('normal');
 const owner=work.ownerId===actorId;const writable=canWrite(work,actorId);const active=work.status!=='completed';
 const tasks=work.subtasks.filter(t=>canSeeWorkItem(work,actorId,t)&&(!expanded||t.goalRevision===work.goalRevision));
 const selected=tasks.find(t=>t.id===taskId);const viewed=tasks.find(t=>t.id===resultTaskId);
 const versions=viewed?getTaskResults(viewed).filter(r=>canSeeWorkItem(work,actorId,r)).sort((a,b)=>b.version-a.version):[];
 const version=versions.find(r=>r.id===resultId)||versions[0];
 const context=selected?taskContext(work,actorId,selected.id):null;
 const person=(id:string)=>work.agents.find(a=>a.agentId===id)?.name||authorName(id);
 const visibleResult=(t:Subtask)=>{const r=latestTaskResult(t);return r&&canSeeWorkItem(work,actorId,r)?r:undefined;};
 const taskTitle=(id:string)=>{const t=work.subtasks.find(x=>x.id===id);return t&&canSeeWorkItem(work,actorId,t)?t.title:'受限成果';};
 const business=(t:Subtask)=>work.decisions.some(d=>d.kind==='business'&&!!d.runId&&(d.runId===t.runId||t.runIds?.includes(d.runId)));
 const maySave=(t:Subtask)=>!business(t)&&writable&&active&&t.goalRevision===work.goalRevision&&t.status!=='running'&&(owner||t.assigneeId===actorId);
 const state=(t:Subtask)=>t.goalRevision!==work.goalRevision?'旧目标':t.status==='running'?'执行中':taskReadiness(work,t)==='outdated'?'输入已更新':taskReadiness(work,t)==='waiting'?'等待依赖':t.status==='done'?'已完成':t.status==='blocked'?'执行未完成':'可开始';
 const open=(t:Subtask,nextMode:'execute'|'dependencies'|'result')=>{setTaskId(t.id);setMode(nextMode);setModalActor(actorId);setContent(visibleResult(t)?.content||'');setDependencies(t.dependsOn||[]);setScenario('normal');setResultTaskId('');};
 const view=(t:Subtask)=>{setResultTaskId(t.id);setResultId('');setViewActor(actorId);};
 useEffect(()=>{setMode(null);setResultTaskId('');setTaskId('');setContent('');},[actorId,work.id]);
 const submit=()=>{if(!selected)return;if(mode==='dependencies'&&!wapi.updateSubtaskDependencies(work.id,selected.id,dependencies))return;if(mode==='result'&&!wapi.saveSubtaskResult(work.id,selected.id,content.trim()))return;if(mode==='execute'&&!wapi.startSubtask(work.id,selected.id,scenario))return;setMode(null);};
 return <><div className={expanded?'cw-shared-results':'cw-subtasks'}>{tasks.map(t=>{
  const r=visibleResult(t);const ready=taskReadiness(work,t);const current=t.goalRevision===work.goalRevision;const running=t.status==='running';const agent=work.agents.some(a=>a.agentId===t.assigneeId);
  const executor=work.agents.find(a=>a.agentId===t.assigneeId);
  const gate=agent?governanceGate(demo.state,t.assigneeId,business(t)?'protected-action':'general',executor?.releaseId):{allowed:true,reason:''};
  const mayRun=writable&&active&&current&&!running&&agent&&(t.status!=='done'||ready==='outdated');
  return <article className={`cw-subtask ${t.status} ${ready==='outdated'?'inputs-outdated':''} ${expanded?'cw-shared-result':''}`} key={t.id}>
   <div className="cw-subtask-top"><span className="cw-subtask-dot">{t.status==='done'&&ready==='ready'?<Check size={11}/>:running?<Clock3 size={11}/>:null}</span><strong>{t.title}</strong></div>
   <div className="cw-subtask-meta"><span>{person(t.assigneeId)}</span><span className={`cw-subtask-state ${ready==='outdated'?'blocked':t.status}`}>{current&&t.status!=='done'&&!gate.allowed?'执行已暂停':state(t)}</span></div>{current&&t.status!=='done'&&!gate.allowed&&<p className="cw-subtask-result">{gate.reason}</p>}
   {!!t.dependsOn?.length&&<div className="cw-dependency-chips">{t.dependsOn.map(id=>{const dependency=work.subtasks.find(x=>x.id===id);const output=dependency&&canSeeWorkItem(work,actorId,dependency)?visibleResult(dependency):undefined;return <span key={id}><GitBranch size={10}/>{taskTitle(id)}{output&&<b>v{output.version}</b>}</span>;})}</div>}
   {r&&<button className="cw-result-link" onClick={()=>view(t)}><FileText size={13}/><span>已提交 · v{r.version}</span><ArrowUpRight size={11}/></button>}
   {expanded&&r&&<p className="cw-shared-result-content">{r.content}</p>}
   {!r&&t.status==='blocked'&&t.result&&<p className="cw-subtask-result">{t.result}</p>}
   {expanded&&!r&&<p className="cw-empty-line">尚未提交成果</p>}
   <div className="cw-subtask-actions">
    {t.runId&&demo.state.runs.some(run=>run.id===t.runId&&canSeeWorkRun(wapi.state.works,actorId,run))&&<button onClick={()=>onNavigate('portal','run',t.runId)}>执行记录<ArrowUpRight size={11}/></button>}
    {writable&&active&&current&&!running&&<Button size="xs" variant="ghost" onClick={()=>open(t,'dependencies')}>设置依赖</Button>}
    {maySave(t)&&<Button size="xs" variant="outline" disabled={!dependenciesReady(work,t)||!taskContext(work,actorId,t.id)} onClick={()=>open(t,'result')}>{r?'修订成果':'提交成果'}</Button>}
    {mayRun&&<Button size="xs" variant="outline" disabled={!gate.allowed||!dependenciesReady(work,t)||!taskContext(work,actorId,t.id)||(business(t)&&!owner)} title={!gate.allowed?gate.reason:undefined} onClick={()=>open(t,'execute')}>{ready==='outdated'?'更新执行':t.status==='blocked'?'重试执行':'开始执行'}<Play/></Button>}
   </div>
  </article>;
 })}{!tasks.length&&<p className="cw-empty-line">暂无可见子任务</p>}</div>
 <Dialog open={!!viewed&&!!version&&viewActor===actorId} onOpenChange={value=>!value&&setResultTaskId('')}><DialogContent className="cw-result-dialog" aria-describedby={undefined}><DialogHeader><DialogTitle>{viewed?.title}</DialogTitle></DialogHeader>{viewed&&version&&<div className="dialog-body cw-result-body"><div className="cw-result-version-row"><select aria-label="子任务成果版本" value={version.id} onChange={e=>setResultId(e.target.value)}>{versions.map(r=><option value={r.id} key={r.id}>v{r.version} · 目标 r{r.goalRevision}</option>)}</select><span>{version.createdAt||'历史成果'}</span></div><DocumentBody content={version.content}/><section className="cw-result-provenance"><h3>采用的成果版本</h3>{version.inputs.length?<ul>{version.inputs.map(input=><li key={input.subtaskId}><span>{taskTitle(input.subtaskId)}</span><code>v{input.version}</code></li>)}</ul>:<p>任务目标与共享资料</p>}{version.runId&&demo.state.runs.some(run=>run.id===version.runId&&canSeeWorkRun(wapi.state.works,actorId,run))&&<button className="text-link" onClick={()=>{setResultTaskId('');onNavigate('portal','run',version.runId);}}>来源执行 {version.runId}<ArrowUpRight size={12}/></button>}<span className="cw-result-author">提交者 · {person(version.createdBy)}</span></section></div>}<DialogFooter><Button variant="outline" onClick={()=>setResultTaskId('')}>关闭</Button>{viewed&&maySave(viewed)&&<Button disabled={!dependenciesReady(work,viewed)} onClick={()=>open(viewed,'result')}>修订成果</Button>}</DialogFooter></DialogContent></Dialog>
 <Dialog open={!!mode&&!!selected&&modalActor===actorId} onOpenChange={value=>!value&&setMode(null)}><DialogContent className="cw-action-dialog cw-task-action-dialog" aria-describedby={undefined}><DialogHeader><DialogTitle>{mode==='dependencies'?'编辑依赖':mode==='result'?(selected&&visibleResult(selected)?'修订成果':'提交成果'):selected&&business(selected)?'确认业务再次执行':selected&&taskReadiness(work,selected)==='outdated'?'更新执行':'执行子任务'}</DialogTitle></DialogHeader>{selected&&<div className="dialog-body cw-form-body"><div className="cw-action-context"><strong>{selected.title}</strong><span>{person(selected.assigneeId)} · 目标 r{selected.goalRevision}</span></div>
 {mode==='dependencies'&&<DependencyPicker work={work} value={dependencies} onChange={setDependencies} excludeId={selected.id}/>}
 {mode==='result'&&<><Field label="成果内容"><Textarea autoFocus rows={8} placeholder="填写结论、依据和待核验事项" value={content} onChange={e=>setContent(e.target.value)}/></Field><InfoTip label="成果共享说明">提交后成为任务共享的工作依据，下游按依赖读取此版本；成果仍需按业务要求核验。修订保留历史，并标记受影响的下游任务。</InfoTip></>}
 {mode==='execute'&&<>{business(selected)&&<Notice tone="warning">将再次执行已确认的业务动作，请先确认上次执行未产生重复提交。此次执行需要负责人确认。</Notice>}<section className="cw-execution-inputs"><h3>本次执行依据</h3>{context?.inputs.length?<ul>{context.inputs.map(input=><li key={input.subtaskId}><span>{taskTitle(input.subtaskId)}</span><code>v{input.version}</code></li>)}</ul>:<p>任务目标与共享资料</p>}{context?<details><summary>查看完整执行上下文</summary><pre>{context.input}</pre></details>:<Notice tone="warning">依赖成果尚未完成、已过时或不在当前历史范围内。</Notice>}</section><Field label="运行情境"><select value={scenario} onChange={e=>setScenario(e.target.value as Run['scenario'])}><option value="normal">正常完成</option><option value="failure">工具异常</option><option value="guardrail">策略拦截</option><option value="timeout">运行超时</option></select></Field></>}
 </div>}<DialogFooter><Button variant="outline" onClick={()=>setMode(null)}>取消</Button><Button disabled={!selected||(mode==='result'&&(!content.trim()||!dependenciesReady(work,selected)||!context))||(mode==='execute'&&(!governanceGate(demo.state,selected.assigneeId,business(selected)?'protected-action':'general',work.agents.find(a=>a.agentId===selected.assigneeId)?.releaseId).allowed||!dependenciesReady(work,selected)||!context||(business(selected)&&!owner)))} onClick={submit}>{mode==='dependencies'?'保存依赖':mode==='result'?'提交成果版本':selected&&business(selected)?'确认再次执行':selected&&taskReadiness(work,selected)==='outdated'?'更新执行':'开始执行'}</Button></DialogFooter></DialogContent></Dialog>
 </>;
}

function SharedWorkContext({work,onNavigate,onAddMaterial}:{work:Work;onNavigate:PageProps['onNavigate'];onAddMaterial:()=>void}){
 const {actorId}=useWorks();const writable=canWrite(work,actorId);
 const materials=work.materials.filter(m=>canSeeWorkItem(work,actorId,m));
 const decisions=work.decisions.filter(d=>d.status==='approved'&&canSeeWorkItem(work,actorId,d));
 return <div className="cw-shared-context"><SectionTitle title="子任务成果" action={<InfoTip label="任务共享上下文说明">目标、资料、决策和已提交成果组成任务共享上下文。下游按依赖读取成果版本；输入更新后需要检查受影响的工作，不自动发起执行。</InfoTip>}/><SubtaskFlow work={work} onNavigate={onNavigate} expanded/><section className="cw-shared-section"><SectionTitle title="共享资料" action={<Button size="icon-xs" variant="ghost" aria-label="添加共享资料" disabled={!writable||work.status==="completed"} onClick={onAddMaterial}><Plus/></Button>}/>{materials.map(m=><article className="cw-shared-material" key={m.id}><FileText size={17}/><div><strong>{m.name}</strong><span>{m.source==='knowledge'?'知识引用':'任务资料'} · {authorName(m.ownerId)}</span><p>{m.detail}</p></div></article>)}{!materials.length&&<p className="cw-empty-line">暂无可见资料</p>}</section><section className="cw-shared-section"><SectionTitle title="已确认决策"/>{decisions.map(d=><article className="cw-shared-decision" key={d.id}><ShieldCheck size={16}/><div><strong>{d.title}</strong><p>{d.detail}</p><span>目标 r{d.goalRevision} · {authorName(d.resolvedBy||d.approverId)}</span></div></article>)}{!decisions.length&&<p className="cw-empty-line">暂无已确认决策</p>}</section></div>;
}
